// TIGHTLY COUPLED (No Abstraction)
class DirectAwsS3Client {
    public void connectToBucketRegionEast(String credentials) {
        System.out.println("Establishing AWS TLS session: " + credentials);
    }
    public void putRawS3BinaryObject(String bucket, byte[] data) {
        System.out.println("Uploaded " + data.length + " bytes to AWS bucket " + bucket);
    }
}

// CLEAN ABSTRACTION (Separating What from How)
abstract class CloudStorage {
    // Contract: WHAT must be done
    public abstract void upload(String path, byte[] data);
}

class S3Storage extends CloudStorage {
    @Override
    public void upload(String path, byte[] data) {
        // HOW AWS handles it
        System.out.println("[AWS S3] Streaming payload to /" + path);
    }
}

class GoogleCloudStorage extends CloudStorage {
    @Override
    public void upload(String path, byte[] data) {
        // HOW GCP handles it
        System.out.println("[GCP Cloud Storage] Writing chunk to bucket /" + path);
    }
}

public class CloudApp {
    public static void main(String[] args) {
        // Client works exclusively with the high-level CloudStorage contract
        CloudStorage storage = new S3Storage();
        storage.upload("reports/2026.pdf", new byte[1024]);
    }
}

