abstract class AlertChannel {
    protected String channelName;
    public AlertChannel(String channelName) {
        this.channelName = channelName;
    }
    // WHAT: Base specification
    public abstract void dispatch(String message);
}

class EmailAlert extends AlertChannel {
    public EmailAlert() { super("EMAIL"); }
    @Override
    public void dispatch(String message) {
        System.out.println("[" + channelName + "] Formatting HTML body -> Sending SMTP packet: " + message);
    }
}

class PagerDutyAlert extends AlertChannel {
    public PagerDutyAlert() { super("PAGERDUTY"); }
    @Override
    public void dispatch(String message) {
        System.out.println("[" + channelName + "] Triggering incident severity P1: " + message);
    }
}

public class AlertService {
    // Caller depends ONLY on the abstraction
    public static void triggerEmergency(AlertChannel channel, String issue) {
        System.out.println("Initiating protocol...");
        channel.dispatch(issue);
    }

    public static void main(String[] args) {
        AlertChannel alert = new PagerDutyAlert();
        triggerEmergency(alert, "Primary Database Connection Pool Depleted");
    }
}

