abstract class Appliance {
    protected String brand;
    public Appliance(String brand) { this.brand = brand; }
    public abstract void turnOn();
}

class Toaster extends Appliance {
    public Toaster(String brand) { super(brand); }
    @Override
    public void turnOn() {
        System.out.println(brand + " heating coils glowing red");
    }
}

class Blender extends Appliance {
    public Blender(String brand) { super(brand); }
    @Override
    public void turnOn() {
        System.out.println(brand + " blades spinning at high speed");
    }
}

public class ApplianceApp {
    public static void main(String[] args) {
        Appliance[] kitchen = new Appliance[] {
            new Toaster("Breville"),
            new Blender("Ninja")
        };
        for (Appliance a : kitchen) {
            a.turnOn();
        }
    }
}

abstract class DocumentExporter {
    protected String title;
    public DocumentExporter(String title) {
        this.title = title;
    }
    public abstract String export(String content);
}

class HtmlExporter extends DocumentExporter {
    public HtmlExporter(String title) {
        super(title);
    }
    @Override
    public String export(String content) {
        return "<h1>" + title + "</h1><p>" + content + "</p>";
    }
}

class MarkdownExporter extends DocumentExporter {
    public MarkdownExporter(String title) {
        super(title);
    }
    @Override
    public String export(String content) {
        return "# " + title + "\n" + content;
    }
}

public class ExporterApp {
    public static void main(String[] args) {
        DocumentExporter[] exporters = new DocumentExporter[] {
            new HtmlExporter("Report"),
            new MarkdownExporter("Summary")
        };
        String content = "System status OK";
        for (DocumentExporter exporter : exporters) {
            System.out.println(exporter.export(content));
        }
    }
}

abstract class TelemetrySensor {
    protected String sensorId;
    public TelemetrySensor(String sensorId) {
        this.sensorId = sensorId;
    }
    public abstract double readMetric();
    public void report() {
        System.out.println(sensorId + " reading: " + String.format("%.1f", readMetric()));
    }
}

class TemperatureSensor extends TelemetrySensor {
    private double tempCelsius;
    public TemperatureSensor(String sensorId, double tempCelsius) {
        super(sensorId);
        this.tempCelsius = tempCelsius;
    }
    @Override
    public double readMetric() {
        return tempCelsius;
    }
}

class PressureSensor extends TelemetrySensor {
    private double psi;
    public PressureSensor(String sensorId, double psi) {
        super(sensorId);
        this.psi = psi;
    }
    @Override
    public double readMetric() {
        return psi;
    }
}

public class TelemetryApp {
    public static void main(String[] args) {
        TelemetrySensor[] sensors = new TelemetrySensor[] {
            new TemperatureSensor("TEMP-01", 24.5),
            new PressureSensor("PRESS-09", 101.3)
        };
        for (TelemetrySensor s : sensors) {
            s.report();
        }
    }
}

