abstract class MessageDigestEngine {
    protected String algorithmName;
    public MessageDigestEngine(String algorithmName) {
        this.algorithmName = algorithmName;
    }
    public abstract String hash(String input);
    public void audit(String data) {
        System.out.println("[" + algorithmName + "] Digest for \"" + data + "\": " + hash(data));
    }
}

class Sha256Engine extends MessageDigestEngine {
    public Sha256Engine() {
        super("SHA-256");
    }
    @Override
    public String hash(String input) {
        return "sha256_mock_digest_" + input.length();
    }
}

class Md5Engine extends MessageDigestEngine {
    public Md5Engine() {
        super("MD5");
    }
    @Override
    public String hash(String input) {
        return "md5_mock_digest_" + input.hashCode();
    }
}

public class CryptoApp {
    public static void main(String[] args) {
        MessageDigestEngine[] engines = new MessageDigestEngine[] {
            new Sha256Engine(),
            new Md5Engine()
        };
        String secret = "secret_payload";
        for (MessageDigestEngine engine : engines) {
            engine.audit(secret);
        }
    }
}
